#include <SPI.h>
#include <nRF24L01.h>
#include <RF24.h>
#include <WiFi.h>
#include <WebServer.h>
#include <BluetoothSerial.h>

// NRF24L01 Radio Setup
RF24 radio(4, 5); 
const byte radioAddress[6] = "00001";

// Bluetooth Setup
BluetoothSerial SerialBT;

// Web Server Setup (WiFi)
WebServer server(80);

// Motor Driver Pins (L298N)
const int IN1 = 12; const int IN2 = 13;
const int IN3 = 14; const int IN4 = 27;

void setup() {
  Serial.begin(115200);

      // Initialize Motors
        pinMode(IN1, OUTPUT); pinMode(IN2, OUTPUT);
          pinMode(IN3, OUTPUT); pinMode(IN4, OUTPUT);
            stopCar();

              // 1. Initialize Radio
                if (radio.begin()) {
                    radio.openReadingPipe(0, radioAddress);
                        radio.setPALevel(RF24_PA_MIN);
                            radio.startListening();
                                Serial.println("Radio Initialized.");
                                  }

                                    // 2. Initialize WiFi Hotspot
                                      WiFi.softAP("Ultimate_ESP32_Car", "12345678");
                                        server.on("/FORWARD", moveForward);
                                          server.on("/STOP", stopCar);
                                            server.begin();
                                              Serial.println("WiFi Hotspot & Server Started.");

                                                // 3. Initialize Classic Bluetooth
                                                  SerialBT.begin("ESP32_Car_Bluetooth");
                                                    Serial.println("Bluetooth Ready to Pair.");
                                                    }

                                                    void loop() {
                                                      // Handle WiFi Phone App commands
                                                        server.handleClient();

                                                          // Handle Classic Bluetooth Serial commands (from a phone Bluetooth terminal app)
                                                            if (SerialBT.available()) {
                                                                char btCmd = SerialBT.read();
                                                                    if (btCmd == 'F') moveForward();
                                                                        if (btCmd == 'S') stopCar();
                                                                          }

                                                                            // Handle NRF24L01 Radio Joystick commands
                                                                              if (radio.available()) {
                                                                                  char radioCmd;
                                                                                      radio.read(&radioCmd, sizeof(radioCmd));
                                                                                          if (radioCmd == 'F') moveForward();
                                                                                              if (radioCmd == 'S') stopCar();
                                                                                                }
                                                                                                }

                                                                                                void moveForward() {
                                                                                                  digitalWrite(IN1, HIGH); digitalWrite(IN2, LOW);
                                                                                                    digitalWrite(IN3, HIGH); digitalWrite(IN4, LOW);
                                                                                                      if(server.client()) server.send(200, "text/plain", "Moving Forward");
                                                                                                      }

                                                                                                      void stopCar() {
                                                                                                        digitalWrite(IN1, LOW); digitalWrite(IN2, LOW);
                                                                                                          digitalWrite(IN3, LOW); digitalWrite(IN4, LOW);
                                                                                                            if(server.client()) server.send(200, "text/plain", "Stopped");
                                                                                                            }
